        {
            age = rand.nextInt(MAX_AGE);
            foodLevel = rand.nextInt(MAX_FOOD_LEVEL);
        }
        else
        {
            age = 0;

            // Chooses a random percentage between 0-18% of the max
            // food level to start at - prevents a self-sustaining
